// Versioned import: stages a validated candidate and diff; never overwrites canonical data.
import {readFile,mkdir,writeFile} from 'node:fs/promises';import {createHash} from 'node:crypto';import {validate,parseUniqueJSON} from './validate.mjs';
const input=process.argv[2];if(!input)throw Error('Usage: node scripts/stage-bundle.mjs candidate.json');const raw=await readFile(input,'utf8');const bundle=parseUniqueJSON(raw);const master=JSON.parse(await readFile('public/data/master.json','utf8'));const result=validate(master,bundle);if(result.errors.length)throw Error(result.errors.join('\n'));let old={entries:{}};try{old=JSON.parse(await readFile(`public/data/${bundle.code}.json`,'utf8'))}catch{}
const changed=Object.keys(bundle.entries).filter(id=>JSON.stringify(bundle.entries[id])!==JSON.stringify(old.entries[id]));const version=createHash('sha256').update(raw).digest('hex').slice(0,16);await mkdir('review/staged',{recursive:true});await writeFile(`review/staged/${bundle.code}-${version}.json`,JSON.stringify({candidate:bundle,previousVersion:old.version||null,changed,removed:Object.keys(old.entries).filter(id=>!bundle.entries[id]),validation:result,stagedAt:new Date().toISOString()},null,2),{flag:'wx'});console.log(`Staged ${bundle.code}-${version}: ${changed.length} changes. Canonical bundle unchanged. Review before explicit promotion.`);
